(()=>{'use strict';
 studioPositions=c=>WalletLayout.positions(c);
 cardHTML=function(c,m=null,full=false){const p=Loyalty.program(c),en=c.cardLanguage==='en',member=m||{stamps:2,points:20,rewards:0,id:'RJ-PREVIEW01',name:en?'Card preview':'معاينة البطاقة'},balance=p.type==='points'?(member.points||0):(member.stamps||0),goal=p.type==='points'?p.pointsCost:c.target,completed=Loyalty.available(member,c)?c.target:p.type==='points'?Math.floor(Math.min(1,balance/goal)*c.target):Math.min(c.target,balance),positions=WalletLayout.positions(c),label=WalletLayout.reward(c,p)||Loyalty.label(c),number=n=>Number(n).toLocaleString(en?'en-US':'ar-SA');
 return `<div class="loyalty-card studio-card wallet-native-card ${full?'studio-full':''}" dir="ltr" lang="${en?'en':'ar'}" style="--card:${esc(c.color||'#204b3c')};--accent:${esc(c.accent||'#d6ff76')}">${c.background?`<img class="studio-background" src="${esc(c.background)}" alt="">`:''}<span class="wallet-shade" style="opacity:${Math.min(.85,Math.max(0,Number(c.backgroundDim)||0)/100)}" aria-hidden="true"></span><div class="wallet-logo">${c.logo?`<img src="${esc(c.logo)}" alt="شعار النشاط">`:`<span dir="auto">${esc(c.name||c.title||'')}</span>`}</div><div class="wallet-balance"><span>${en?'BALANCE':'الرصيد'}</span><strong>${number(balance)} / ${number(goal)}</strong></div><div class="studio-stamps"><div class="studio-stamp-grid">${(c.progressDisplay&&c.progressDisplay!=='icons'?[]:positions).map((pos,i)=>{const earned=i<completed,src=earned?c.stampImage:(c.stampEmptyImage||c.stampImage);return `<span class="studio-stamp ${earned?'earned':''}" data-item="${i}" style="left:${pos.x}%;top:${pos.y}%;--wallet-item-width:${pos.size/WalletLayout.width*100}%;--stamp-size:${pos.size}px" title="${earned?'زيارة مكتملة':'زيارة قادمة'}">${src?`<img src="${esc(src)}" alt="${earned?'بعد الزيارة':'قبل الزيارة'}">`:WalletLayout.art(c,earned)}</span>`;}).join('')}</div>${WalletLayout.progressSVG(c,member)}${c.progressDisplay==='image'&&c.stampImage&&c.stampEmptyImage?`<div class="wallet-image-fill"><img src="${esc(c.stampEmptyImage)}" alt="شكل التعبئة الفارغ"><img src="${esc(c.stampImage)}" alt="التقدم ${WalletLayout.progress(c,member).percent}%" style="clip-path:inset(0 ${(1-WalletLayout.progress(c,member).ratio)*100}% 0 0)"></div>`:''}</div><div class="studio-code ${p.barcodeFormat==='code128'?'wide-code':''}">${codeHTML(c,member)}</div><div class="studio-bottom"><div class="studio-reward"><span>${en?'Reward':'المكافأة'}</span><strong dir="auto">${esc(label)}</strong></div></div></div>`;
 };
 const beforePreview=updatePreview;updatePreview=function(){if(draft){draft.elementLayout=WalletLayout.positions(draft);draft.itemCoordinateSpace='card';}beforePreview();};
 const beforeDesign=designHTML;designHTML=function(){const box=document.createElement('div');box.innerHTML=beforeDesign().replace('شكل العنصر قبل الزيارة وبعدها، وطريقة عرض العداد.','صور العناصر قبل الزيارة وبعدها، وحجمها ومكانها.').replace('اسم المكافأة وصورتها، في مكان واحد.','اسم المكافأة وشروط استحقاقها.').replace('اسحب كل عنصر إلى أي مكان على البطاقة بالكامل، أو اختره وعدّل موقعه من هنا. تجنب تغطية الباركود حتى يبقى قابلًا للمسح.','اسحب العنصر داخل مساحة التصميم المتاحة، أو عدّل مكانه وحجمه من هنا. حدود الحركة تحمي الشعار والرصيد والباركود من التداخل.');
 const unsupported=['category','showHeadline','headline','eyebrow','showProgramLabel','hideBalance','balanceStyle','balanceX','balanceY','logoSize','logoX','logoY','headlineX','headlineY','rewardImageSize','rewardX','rewardY','effectsEnabled','stampEmphasis','elementsGlow','completedGlow','backgroundMode','hideIdentity','glassShine','pointsDisplay','stampX','stampY'];
 for(const key of unsupported)box.querySelectorAll(`[data-card="${key}"],[data-enhance="${key}"],[data-studio="${key}"]`).forEach(el=>(el.closest('label.field,label.studio-toggle,.field')||el).remove());
 box.querySelectorAll('#custom-category-field,.studio-tools,.studio-presets,[data-action="pattern"]').forEach(el=>{const target=el.closest('.field')||el;target.remove();});
 box.querySelectorAll('.logo-edit-controls').forEach(el=>el.remove());
 box.querySelector('#reward-image-file')?.closest('.field')?.remove();
 box.querySelectorAll('.card-option-panel,.editor-advanced').forEach(el=>{if(!el.querySelector('input,select,textarea,button'))el.remove();});
 box.querySelectorAll('p.line-meta,p.sub').forEach(el=>{if(/اللمعة|٩٠٠|١٦٠٠|نستخدم علامة الهدية|عند إيقاف التمييز/.test(el.textContent))el.remove();});
 const name=box.querySelector('[data-card="name"]');if(name){name.closest('.field').querySelector('span').textContent='اسم النشاط · يظهر على البطاقة عند عدم وجود شعار';const small=name.closest('.field').querySelector('small');if(small)small.textContent='مع رفع الشعار، يظهر الشعار وحده. عنوان البطاقة يبقى في لوحة التحكم.';}
 const previewNote=box.querySelector('.preview-note');if(previewNote)previewNote.textContent='معاينة قالب Apple بالخلفية الكاملة. الشعار والرصيد والرمز والمكافأة ثابتة؛ الخط والمسافات الدقيقة قد تختلف بحسب إصدار iOS. Google والأجهزة الأقدم لها قالب مختلف.';
 const progressPanel=box.querySelector('#stamp-file')?.closest('details')||box.querySelector('.editor-grid>.panel');progressPanel?.insertAdjacentHTML('afterbegin','<label class="field"><span>طريقة عرض التقدم</span><select data-card="progressDisplay">'+[['icons','عناصر ورموز'],['bar','شريط تعبئة'],['percent','نسبة مئوية'],['both','شريط مع نسبة'],['image','تعبئة بصورة مخصصة'],['none','لا شيء']].map(([v,t])=>'<option value="'+v+'" '+((draft.progressDisplay||'icons')===v?'selected':'')+'>'+t+'</option>').join('')+'</select><small>مستقل عن نوع المكافأة. يتحدث مع الرصيد في المحفظة؛ موضع العرض يختلف بين Apple وGoogle.</small></label>');
 if((draft.progressDisplay||'icons')!=='icons'){box.querySelector('.icon-options')?.closest('.field')?.remove();box.querySelectorAll('[data-item-control]').forEach(e=>e.closest('.field')?.remove());if(draft.progressDisplay!=='image')for(const id of ['#stamp-file','#stamp-empty-file'])box.querySelector(id)?.closest('.field')?.remove();}
 if(draft.progressDisplay==='image'){for(const [selector,label] of [['#stamp-file','صورة الشكل الممتلئ'],['#stamp-empty-file','صورة الشكل الفارغ']]){const field=box.querySelector(selector)?.closest('.field');if(field){const title=field.querySelector('span');if(title)title.textContent=label;const small=field.querySelector('small');if(small)small.textContent='PNG بخلفية شفافة. الصورتان بنفس المقاس والمحاذاة؛ التعبئة من اليسار إلى اليمين.';}}}
 const panel=box.querySelector('.editor-grid>.panel');panel?.insertAdjacentHTML('afterbegin','<div class="notice wallet-editor-note">تصميم Apple Wallet: حرّك عناصر الولاء داخل المساحة المخصصة لها. تُحفظ مناطق الشعار والرصيد والرمز والمكافأة من التداخل، وتُطبق الحدود نفسها عند إصدار البطاقة.</div>');
 box.querySelectorAll('[data-item-control="y"],[data-studio="stampY"]').forEach(el=>{el.min='3';el.max='51';});
 const background=box.querySelector('#background-file');box.querySelectorAll('.background-size-guide').forEach(el=>el.remove());const backgroundHelp=background?.closest('.field')?.querySelector('small');if(backgroundHelp)backgroundHelp.textContent='PNG أو JPG أو WebP · حتى ٥ ميجابايت';background?.closest('.field')?.insertAdjacentHTML('beforeend','<small>خلفية كاملة: ٦٩٠ × ١٠١٠ بكسل. استخدم منطقة الوسط العليا للعناصر، واترك منطقة الرمز والمكافأة أسفلها واضحة.</small>');
 return box.innerHTML;
 };
 const beforeBind=bindEditor;bindEditor=function(){beforeBind();document.querySelector('[data-card="progressDisplay"]')?.addEventListener('change',()=>{render();});const preview=document.querySelector('#card-preview');if(!preview)return;preview.addEventListener('pointermove',()=>{if(!draft?.elementLayout)return;draft.elementLayout=WalletLayout.positions(draft);draft.itemCoordinateSpace='card';preview.querySelectorAll('.studio-stamp').forEach((el,i)=>{const pos=draft.elementLayout[i];if(pos){el.style.left=pos.x+'%';el.style.top=pos.y+'%';}});});preview.addEventListener('pointerup',()=>{draft.elementLayout=WalletLayout.positions(draft);draft.itemCoordinateSpace='card';},true);};
 const beforeOwner=ownerHTML;ownerHTML=function(){const result=beforeOwner();return view==='mycards'?result.replace('المقاس والتصميم مطابقان لبطاقة الجوال داخل الموقع. مرّر الماوس أو اضغط لإظهار الباركود.','معاينة قالب Apple بالخلفية الكاملة. مرّر الماوس أو اضغط لإظهار الباركود؛ الخط والمسافات الدقيقة تعتمد على إصدار iOS.'):result;};
 render();
})();
